const PUBLICAS = ['id', 'proveedor', 'nif', 'numero', 'fecha', 'pedido', 'concepto', 'base', 'iva_pct', 'cuota_iva',
  'total', 'vencimiento', 'fecha_pago', 'estado', 'incidencias', 'decidido_en'];

// Devuelve las facturas de ejemplo (comunes a todos, de solo lectura) y debajo las que ha enviado el visitante,
// en el orden en que las envió y marcadas como suyas. Nunca expone el sid.
const q = $('Listar facturas').first().json.query ?? {};
const sid = /^[a-f0-9]{32}$/.test(String(q.sid ?? '')) ? String(q.sid) : null;
const todas = $input.all().map((i) => i.json);
const publica = (r) => {
  const f = { tuya: r.sid !== 'demo' };
  for (const k of PUBLICAS) f[k] = r[k];
  return f;
};
const demo = todas.filter((r) => r.sid === 'demo').sort((a, b) => String(a.fecha).localeCompare(String(b.fecha)));
const propias = sid === null ? [] : todas
  .filter((r) => r.sid === sid)
  .sort((a, b) => Number(a.creado_ms) - Number(b.creado_ms));
return [{ json: { filas: demo.concat(propias).map(publica) } }];

// Datos maestros inventados: fichas de proveedor (con la cuenta bancaria registrada) y pedidos de compra.
const PROVEEDORES = {
  B48123456: { nombre: 'Aceros del Norte, S.L.', iban: 'ES9121000418450200051332', plazo: 60 },
  A46234567: { nombre: 'Bobinas Levante, S.A.', iban: 'ES6000491500051234567892', plazo: 60 },
  B50345678: { nombre: 'Transportes Ebro, S.L.', iban: 'ES1720852066623456789011', plazo: 30 },
  B28456789: { nombre: 'Suministros Industriales Gil, S.L.', iban: 'ES3001820815200201234567', plazo: 30 },
  B26567890: { nombre: 'Mantenimiento Técnico Arnedo, S.L.', iban: 'ES4521003915102200123456', plazo: 30 },
};
// Proveedores que pueden enviar facturas pero no tienen ficha (no están dados de alta).
const SIN_FICHA = { B31678901: 'Talleres Ribera, S.L.' };
const PEDIDOS = {
  'PC-2026-0412': { nif: 'B48123456', concepto: 'Bobina de acero galvanizado 1,5 mm (12 t)', base: 10680 },
  'PC-2026-0415': { nif: 'A46234567', concepto: 'Bobina prelacada RAL 9002 (8 t)', base: 9120 },
  'PC-2026-0418': { nif: 'B50345678', concepto: 'Portes de octubre (14 viajes)', base: 2380 },
  'PC-2026-0421': { nif: 'B28456789', concepto: 'EPIs y guantes anticorte', base: 845.6 },
  'PC-2026-0423': { nif: 'B26567890', concepto: 'Cambio de rodamientos de la Perfiladora 2', base: 1940 },
  'PC-2026-0426': { nif: 'B48123456', concepto: 'Fleje de acero 0,8 mm (5 t)', base: 4350 },
  'PC-2026-0427': { nif: 'B48123456', concepto: 'Chapa lisa 2 mm (3 t)', base: 2910 },
  'PC-2026-0430': { nif: 'B28456789', concepto: 'Juego de cuchillas para la cizalla', base: 1275 },
};
const DIA_MS = 24 * 3600 * 1000;
const r2 = (n) => Math.round(n * 100) / 100;
const eur = (n) => Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const limpiaIban = (s) => String(s ?? '').replace(/\s+/g, '').toUpperCase();
const isoD = (d) => d.toISOString().slice(0, 10);
const nombreDe = (nif) => PROVEEDORES[nif]?.nombre ?? SIN_FICHA[nif] ?? `Proveedor ${nif}`;

// Vence a los días de plazo de la ficha (30 si no hay ficha) y se paga en la primera remesa (día 10 o 25) desde
// el vencimiento, o desde hoy si el vencimiento ya pasó.
function plazos(fecha, nif, hoy) {
  const v = new Date(Date.parse(fecha + 'T00:00:00Z') + (PROVEEDORES[nif]?.plazo ?? 30) * DIA_MS);
  let d = new Date(Math.max(v.getTime(), Date.parse(hoy + 'T00:00:00Z')));
  while (![10, 25].includes(d.getUTCDate())) d = new Date(d.getTime() + DIA_MS);
  return { vencimiento: isoD(v), fecha_pago: isoD(d) };
}

// Las cinco comprobaciones de contabilidad. `otras` son las facturas ya registradas que ve este visitante.
function comprobar(f, otras) {
  const p = PROVEEDORES[f.nif];
  const c = [];
  c.push({ nombre: 'Proveedor dado de alta', ok: !!p, detalle: p ? `${p.nombre} (${f.nif})` : `${nombreDe(f.nif)} (${f.nif}) no tiene ficha de proveedor` });

  const esperado = r2(f.base * (1 + f.iva_pct / 100));
  const cuadra = Math.abs(esperado - f.total) < 0.011;
  c.push({ nombre: 'Base + IVA = total', ok: cuadra, detalle: cuadra
    ? `${eur(f.base)} + ${f.iva_pct} % de IVA = ${eur(f.total)}`
    : `${eur(f.base)} + ${f.iva_pct} % de IVA son ${eur(esperado)}, y la factura dice ${eur(f.total)}` });

  const clave = (s) => String(s).trim().toUpperCase();
  const dup = otras.find((o) => o.nif === f.nif && clave(o.numero) === clave(f.numero));
  c.push({ nombre: 'No está duplicada', ok: !dup, detalle: dup
    ? `La factura ${dup.numero} de este proveedor ya se registró el ${dup.fecha} (${String(dup.estado).toLowerCase()})`
    : 'Número nuevo para este proveedor' });

  const ped = PEDIDOS[f.pedido];
  let okPed = false;
  let detPed;
  if (!f.pedido) detPed = 'La factura no indica ningún pedido de compra';
  else if (!ped || ped.nif !== f.nif) detPed = `El pedido ${f.pedido} no es de este proveedor`;
  else {
    const usada = otras.find((o) => o.pedido === f.pedido && o.estado !== 'Rechazada');
    const dif = r2(f.base - ped.base);
    if (usada) detPed = `El pedido ${f.pedido} ya se facturó con la ${usada.numero}`;
    else if (Math.abs(dif) > Math.max(1, ped.base * 0.005)) detPed = `El pedido ${f.pedido} es de ${eur(ped.base)} y la factura cobra ${eur(Math.abs(dif))} de ${dif > 0 ? 'más' : 'menos'}`;
    else { okPed = true; detPed = `Pedido ${f.pedido}: ${ped.concepto}`; }
  }
  c.push({ nombre: 'Coincide con el pedido', ok: okPed, detalle: detPed });

  const iban = limpiaIban(f.iban);
  const okIban = !!p && iban === p.iban;
  c.push({ nombre: 'Cuenta bancaria de la ficha', ok: okIban, detalle: !p
    ? 'No hay ficha con la que comparar la cuenta'
    : okIban ? `La cuenta termina en ${p.iban.slice(-4)}, como en la ficha`
      : `Pide el pago en una cuenta que termina en ${iban.slice(-4)} y la ficha dice ${p.iban.slice(-4)}: confirmar por teléfono antes de pagar` });
  return c;
}

// Valida la factura que "envía" el visitante, le pasa las cinco comprobaciones y decide si se contabiliza
// sola o queda retenida para que la revise contabilidad.
const b = $('Crear factura').first().json.body ?? {};
const todas = $input.all().map((i) => i.json).filter((r) => r.sid);
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const propias = todas.filter((r) => r.sid === sid);
const demo = todas.filter((r) => r.sid === 'demo');
if (propias.length >= 20) return fallo('Has llegado al máximo de 20 facturas de prueba. Se borran solas a las 2 horas.', 429);
if (todas.length - demo.length >= 400) return fallo('La demo está llena ahora mismo. Vuelve dentro de un rato.', 429);

const nif = String(b.nif ?? '').trim().toUpperCase();
if (!PROVEEDORES[nif] && !SIN_FICHA[nif]) return fallo('Proveedor: elige uno de la lista');
const numero = String(b.numero ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 20);
if (!numero) return fallo('Número de factura: escríbelo');
const hoy = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
const fecha = String(b.fecha ?? '');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || Number.isNaN(Date.parse(fecha + 'T00:00:00Z'))) return fallo('Fecha: formato AAAA-MM-DD');
if (fecha > hoy) return fallo('La fecha de la factura no puede ser posterior a hoy.');
if ((Date.parse(hoy) - Date.parse(fecha)) / DIA_MS > 120) return fallo('La demo admite facturas de los últimos 120 días.');
const pedido = String(b.pedido ?? '');
if (pedido && !PEDIDOS[pedido]) return fallo('Pedido: elige uno de la lista o "Sin pedido"');
const base = r2(Number(b.base));
if (!Number.isFinite(base) || base <= 0 || base > 1000000) return fallo('Base imponible: un importe mayor que 0');
const iva_pct = Number(b.iva_pct);
if (![21, 10, 4].includes(iva_pct)) return fallo('IVA: elige 21, 10 o 4 %');
const total = r2(Number(b.total));
if (!Number.isFinite(total) || total <= 0 || total > 2000000) return fallo('Total: un importe mayor que 0');
const iban = limpiaIban(b.iban);
if (!/^[A-Z]{2}\d{2}[0-9A-Z]{11,30}$/.test(iban)) return fallo('Cuenta bancaria: escribe un IBAN (por ejemplo, ES91 2100 0418 4502 0005 1332)');

const f = { nif, numero, pedido, base, iva_pct, total, iban };
const comprobaciones = comprobar(f, demo.concat(propias));
const fallos = comprobaciones.filter((c) => !c.ok);
const estado = fallos.length ? 'Pendiente de revisar' : 'Contabilizada';
const p = plazos(fecha, nif, hoy);

return [{ json: { ok: true, fila: {
  sid, proveedor: nombreDe(nif), nif, numero, fecha, pedido, concepto: PEDIDOS[pedido]?.concepto ?? 'Sin pedido',
  base, iva_pct, cuota_iva: r2(total - base), total, iban,
  vencimiento: p.vencimiento, fecha_pago: estado === 'Contabilizada' ? p.fecha_pago : '',
  estado, incidencias: fallos.map((c) => c.detalle).join('; '),
  comprobaciones: JSON.stringify(comprobaciones), decidido_en: '', creado_ms: Date.now(),
} } }];

const PUBLICAS = ['id', 'proveedor', 'nif', 'numero', 'fecha', 'pedido', 'concepto', 'base', 'iva_pct', 'cuota_iva',
  'total', 'vencimiento', 'fecha_pago', 'estado', 'incidencias', 'decidido_en'];

// Devuelve la factura registrada y el correo que el buzón de facturas mandaría a contabilidad,
// con el resultado de cada comprobación. En la demo no sale ningún correo.
const r = $('Guardar factura demo').first().json;
const factura = { tuya: true };
for (const k of PUBLICAS) factura[k] = r[k];
const comprobaciones = JSON.parse(r.comprobaciones || '[]');

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
