const fecha = (s) => (s ? s.split('-').reverse().join('/') : '');
const corto = r.proveedor.replace(/,? S\.[LA]\.$/, '');
const n = comprobaciones.filter((c) => !c.ok).length;
const asunto = n
  ? `⚠ Factura retenida · ${corto} ${r.numero} · ${eur(r.total)} · ${n} ${n === 1 ? 'incidencia' : 'incidencias'}`
  : `Factura contabilizada · ${corto} ${r.numero} · ${eur(r.total)} · pago el ${fecha(r.fecha_pago)}`;
const fila = (k, v) => `<tr><td style="padding:3px 12px 3px 0;color:#555">${k}</td><td style="padding:3px 0"><b>${v}</b></td></tr>`;
const check = (c) => `<tr><td style="padding:3px 8px 3px 0;color:${c.ok ? '#067647' : '#b42318'};font-weight:bold">${c.ok ? '✓' : '✗'}</td>`
  + `<td style="padding:3px 0"><b>${esc(c.nombre)}</b><br><span style="color:#555">${esc(c.detalle)}</span></td></tr>`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
${n ? `<p style="padding:10px;background:#fef3f2;border-left:4px solid #b42318"><b>Factura retenida:</b> no se pagará hasta que alguien de contabilidad la revise.</p>`
    : `<p style="padding:10px;background:#ecfdf3;border-left:4px solid #067647"><b>Todo cuadra:</b> apuntada en el libro de facturas recibidas y programada para pago.</p>`}
<table>
${fila('Proveedor', `${esc(r.proveedor)} · ${esc(r.nif)}`)}
${fila('Factura', `${esc(r.numero)} del ${fecha(r.fecha)}`)}
${fila('Pedido', r.pedido ? `${esc(r.pedido)} · ${esc(r.concepto)}` : 'Sin pedido')}
${fila('Importe', `${eur(r.base)} + ${r.iva_pct} % IVA (${eur(r.cuota_iva)}) = ${eur(r.total)}`)}
${fila('Vencimiento', fecha(r.vencimiento))}
${r.fecha_pago ? fila('Pago previsto', `${fecha(r.fecha_pago)} (remesa de los días 10 y 25)`) : ''}
</table>
<p style="margin:14px 0 4px"><b>Comprobaciones</b></p>
<table>${comprobaciones.map(check).join('')}</table>
<p style="color:#888;font-size:12px">Leída del PDF adjunto por el buzón de facturas · n8n</p>
</div>`;

return [{ json: { ok: true, factura, comprobaciones, correo: { de: 'Buzón de facturas', para: 'Contabilidad', asunto, html } } }];

