// Comprueba que la factura existe, es del visitante y está pendiente de revisar, y calcula el estado nuevo.
// Si se aprueba, se paga a la cuenta de la ficha, nunca a la que venga en la factura.
const b = $('Decidir factura').first().json.body ?? {};
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const id = Number(b.id);
if (!Number.isInteger(id) || id < 1) return fallo('Factura no válida');
if (!['pagar', 'rechazar'].includes(b.decision)) return fallo('Decisión no válida');

const r = $input.all().map((i) => i.json).find((x) => x.sid === sid && Number(x.id) === id);
if (!r) return fallo('No se encuentra esa factura. Las de prueba se borran a las 2 horas; las de ejemplo no se pueden cambiar.', 404);
if (r.estado !== 'Pendiente de revisar') return fallo(`Esa factura ya está ${String(r.estado).toLowerCase()}.`, 409);

const ahora = $now.setZone('Europe/Madrid');
const estado = b.decision === 'pagar' ? 'Contabilizada' : 'Rechazada';
const fecha_pago = estado === 'Contabilizada' ? plazos(r.fecha, r.nif, ahora.toFormat('yyyy-MM-dd')).fecha_pago : '';
const decidido_en = ahora.toFormat('yyyy-MM-dd HH:mm');
return [{ json: { ok: true, id, sid, estado, fecha_pago, decidido_en, fila: { ...r, estado, fecha_pago, decidido_en },
  iban_ficha: PROVEEDORES[r.nif]?.iban ?? '' } }];

const PUBLICAS = ['id', 'proveedor', 'nif', 'numero', 'fecha', 'pedido', 'concepto', 'base', 'iva_pct', 'cuota_iva',
  'total', 'vencimiento', 'fecha_pago', 'estado', 'incidencias', 'decidido_en'];

